from gapmod import K

C5 = "c-7ffadedb3906"
C6 = "c-7e0b1f4942db"
C7 = "c-cbba2e56c4a9"

K("fw-5why", C5, "s-d4620b924552", "Five whys", "C5 · Khung", "S1 Năm lần vì sao", "Analytical Thinking and Structured Problem Solving using Frameworks",
    ("Hỏi vì sao đến khi gặp một việc xoay được. Năm không phải là số thiêng", "Ask why until you hit a job you can turn. Five is not a sacred number."),
    ("Để «do con người» không được phép kết thúc một chuỗi vì sao.", "So “human error” is not allowed to end a chain of whys."),
    ("C0 đã nói nguyên nhân là cái xoay được. 5 Whys là một cách hỏi tiếp, không phải một nghi lễ đủ năm câu.", "C0 already said a cause is something you can turn. Five whys is a way to keep asking, not a ritual of five sentences."),
    ("dừng ở nút xoay", "stop at a lever"), ("dừng ở «do người»", "stop at “a person”"),
    ("Mỗi vì sao phải là một cơ chế, không phải một tính từ. Dừng khi câu tiếp theo là một thay đổi trong quy trình mà hạn này làm được.", "Each why has to be a mechanism, not an adjective. Stop when the next sentence is a process change this window can make."),
    ("«Nhân viên quên» là một chỗ dừng quá sớm. Câu sau có thể là «không có checklist trước khi gửi». Cái đó xoay được.", "“The staff forgot” is too early a stop. The next sentence might be “there is no checklist before sending”. That one you can turn."),
    ("Dừng ở quy trình. Đừng dừng ở một người.", "Stop at a process. Don't stop at a person."),
    ("Ví dụ minh họa: form sai. Vì sao: thiếu trường. Vì sao: mẫu cũ. Vì sao: không ai được giao việc đổi mẫu. Việc giao người cập nhật mẫu là một nút. Không cần đủ năm nếu nút đã hiện.", "Illustration: a bad form. Why: a missing field. Why: an old template. Why: nobody was assigned to change the template. Assigning that update is a lever. You don't need all five if the lever is already visible."),
    [("Mỗi câu là một cơ chế, viết được thành một việc.", "Each sentence is a mechanism, writable as a job."), ("«Do con người» thì hỏi quy trình nào để họ làm đúng.", "“A person did it” means you ask which process would have them do it right."), ("Đủ nút thì dừng, kể cả chưa đủ năm. Chưa có nút thì đừng dừng ở năm.", "If you have a lever, stop, even before five. If you have no lever, don't stop just because you hit five.")],
    ("Năm là một gợi ý đếm, không phải một định lý. Chuỗi vì sao trên giấy không chứng minh nguyên nhân. Nó là một giả thuyết để đem ra đo, đúng như buổi làm-và-đo ở C0. Một chuỗi dừng ở «thị trường» hoặc «ý thức kém» là một chuỗi chưa có nút.", "Five is a counting hint, not a theorem. A chain of whys on paper does not prove a cause. It is a hypothesis to go and measure, the same way C0's do-and-measure session works. A chain that stops at “the market” or “poor awareness” is a chain with no lever."),
    ("Năm câu không cứu một chỗ dừng ở «do người».", "Five sentences do not save a stop at “a person”."),
)
K("fw-spin", C5, "s-d4620b924552", "SPIN", "C5 · Khung", "S1 Bốn kiểu câu hỏi", "Analytical Thinking and Structured Problem Solving using Frameworks",
    ("SPIN là bốn kiểu câu hỏi. Không phải một kịch bản bắt người ta gật", "SPIN is four kinds of question. Not a script that makes someone nod."),
    ("Để một buổi hỏi hàng không biến thành một mánh bán.", "So a questioning session does not turn into a sales trick."),
    ("5 Whys đi xuống một cơ chế. SPIN đi ngang một cuộc nói: tình hình, vấn đề, hệ quả, rồi cái được nếu giải.", "Five whys goes down into one mechanism. SPIN goes across a conversation: situation, problem, implication, then the payoff if it is solved."),
    ("bốn kiểu hỏi", "four kinds of question"), ("một kịch bản gài", "a script that traps"),
    ("Situation hỏi việc đang chạy thế nào. Problem hỏi chỗ đang kẹt. Implication hỏi kẹt đó kéo theo gì. Need-payoff hỏi nếu hết kẹt thì cái gì khá lên.", "Situation asks how the job runs now. Problem asks where it is stuck. Implication asks what the stuck part drags with it. Need-payoff asks what gets better if it is unstuck."),
    ("Hỏi xoáy cho đối phương phải nói «có» không phải SPIN. Đó là một mánh. SPIN không chứng minh một giải pháp.", "Pushing questions until the other person must say “yes” is not SPIN. That is a trick. SPIN does not prove a solution."),
    ("Dùng bốn kiểu để hiểu việc. Đừng dùng để ép một cái gật.", "Use the four kinds to understand the job. Don't use them to force a nod."),
    ("Ví dụ minh họa: situation là «mấy form một tuần». Problem là «không biết kênh nào đáng tiền». Implication là «ngân sách tháng sau chốt trên cảm giác». Need-payoff là «một thước để cắt một kênh». Không câu nào là một hợp đồng.", "Illustration: situation is “how many forms a week”. Problem is “we don't know which channel is worth the money”. Implication is “next month's budget closes on a feeling”. Need-payoff is “a measure that can cut a channel”. None of those sentences is a contract."),
    [("Tình hình: các số đang có, không phải lời khen.", "Situation: the numbers you have, not a compliment."), ("Vấn đề: một chỗ kẹt, không phải một sản phẩm.", "Problem: one stuck place, not a product."), ("Hệ quả và cái được: để họ nói, đừng điền hộ.", "Implication and payoff: let them say it. Don't fill it in for them.")],
    ("Bốn chữ là situation, problem, implication, need-payoff. Thứ tự giúp cuộc nói không nhảy từ một lời chào sang một báo giá. Nó không tạo nhu cầu. Một câu need-payoff do bạn viết sẵn trong miệng khách là một câu bạn đang gán. Ghi lại câu họ nói, tách số và ý kiến như C0.", "The four words are situation, problem, implication, need-payoff. The order keeps a conversation from jumping from a hello to a quote. It does not create a need. A need-payoff sentence you wrote in the customer's mouth is a sentence you are assigning. Write down what they said, and split numbers from opinions the way C0 did."),
    ("SPIN không làm ai đúng. Nó chỉ xếp câu hỏi.", "SPIN does not make anyone right. It only orders the questions."),
)
K("fw-ask", C5, "s-dd8d140c198d", "A question is not a verdict", "C5 · Khung", "S2 Câu hỏi chưa phải kết", "Analytical Thinking and Structured Problem Solving using Frameworks",
    ("Một câu hỏi chưa phải một kết luận", "A question is not a verdict."),
    ("Để một buổi phỏng vấn không bị viết thành một khuyến nghị khi mới chỉ có câu hỏi.", "So an interview session is not written up as a recommendation when all you have are questions."),
    ("SPIN đã là các kiểu câu hỏi. Buổi sau vẫn là hỏi, chưa phải chấm.", "SPIN was the kinds of question. The next session is still asking, not scoring."),
    ("còn đang hỏi", "still asking"), ("đã kết luận", "already a verdict"),
    ("Danh sách câu hỏi là một dụng cụ. Câu trả lời mới là nguyên liệu. Nguyên liệu chưa kiểm thì chưa thành khuyến nghị.", "A list of questions is a tool. The answers are the material. Unchecked material is not a recommendation yet."),
    ("Năm câu hỏi hay không bằng một số đo lại được.", "Five good questions are not equal to one number you can remeasure."),
    ("Ghi câu hỏi ở một cột, câu trả lời ở cột kia, kết luận chỉ khi đã có thước.", "Write questions in one column, answers in the other. A conclusion only when you have a measure."),
    ("Ví dụ minh họa: «Anh có thấy kênh này yếu không?» là một câu hỏi. Câu «yếu» không phải một kết. Kết cần ngưỡng đã viết ở C0.", "Illustration: “Do you feel this channel is weak?” is a question. The word “weak” is not a result. A result needs the threshold written in C0."),
    [("Đừng biến một câu hỏi thành một heading kết luận.", "Don't turn a question into a conclusion heading."), ("Một câu trả lời là ý kiến thì để cột ý kiến.", "An answer that is an opinion stays in the opinion column."), ("Khuyến nghị phải trỏ về một thước.", "A recommendation has to point at a measure.")],
    ("Buổi Interviewing Frameworks thứ hai trong giáo trình vẫn là cách hỏi, không phải một bài chấm giấu. Không có một thang điểm nào biến một cuộc nói thành sự thật. Muốn kết luận thì quay lại làm-và-đo.", "The second Interviewing Frameworks session in the syllabus is still about how to ask, not a hidden exam. No score turns a conversation into the truth. If you want a conclusion, go back to do-and-measure."),
    ("Hỏi xong chưa phải biết.", "Having asked is not the same as knowing."),
)
K("fw-bmc", C5, "s-47fa04eb0118", "Business model canvas", "C5 · Khung", "S4 Chín ô", "Analytical Thinking and Structured Problem Solving using Frameworks",
    ("Chín ô là chín giả thuyết. Điền chữ không phải bằng chứng", "Nine boxes are nine hypotheses. Filling them with words is not evidence."),
    ("Để một canvas đã tô màu không được mang ra như một nghiên cứu thị trường.", "So a colored-in canvas is not carried out as market research."),
    ("Câu hỏi chưa phải kết. Canvas là một cách trải chín câu, vẫn là giả thuyết cho đến khi có số.", "A question is not a verdict. A canvas is a way to lay out nine sentences, still hypotheses until there is a number."),
    ("chín giả thuyết", "nine hypotheses"), ("chín sự thật", "nine facts"),
    ("Business model canvas có chín ô: phân khúc, giá trị, kênh, quan hệ khách, dòng doanh thu, nguồn lực, hoạt động chính, đối tác, cơ cấu chi phí.", "The business model canvas has nine boxes: segments, value, channels, customer relationships, revenue streams, resources, key activities, partners, cost structure."),
    ("Viết «khách trẻ thích trải nghiệm» trong ô phân khúc là một giả thuyết. Không có một cuộc đếm nào ở trong cây bút.", "Writing “young customers like experiences” in the segment box is a hypothesis. There is no count inside the pen."),
    ("Mỗi ô một câu kiểm được, hoặc ghi là chưa có căn.", "Each box gets a sentence you can check, or it is marked as not yet grounded."),
    ("Ví dụ minh họa: ô kênh ghi «TikTok». Việc kiểm là tỷ lệ form trên click của kênh đó, cùng hạt. Không kiểm được thì ô vẫn là một lời.", "Illustration: the channel box says “TikTok”. The check is that channel's form rate per click, at one grain. If you cannot check it, the box is still a sentence."),
    [("Điền cả chín ô, đừng chỉ tô ô bạn thích.", "Fill all nine. Don't only color the box you like."), ("Mỗi ô: đâu là số sẽ làm ô đó sai.", "Each box: what number would make that box wrong."), ("Chưa có số thì đừng trình bày như kết quả nghiên cứu.", "With no number, don't present it as research findings.")],
    ("Chín ô nhìn một mô hình kinh doanh, không thay một thước SMART. Ô doanh thu và ô chi phí không tự thành một báo cáo lãi lỗ. Chúng là các giả thuyết về tiền từ đâu và tiền đi đâu. Một canvas của một ý tưởng mới và một canvas của một việc đang chạy đều chỉ là giấy, cho đến khi từng ô có một cách đo.", "The nine boxes look at a business model. They do not replace a SMART measure. The revenue box and the cost box do not automatically become a profit-and-loss statement. They are hypotheses about where money comes from and where it goes. A canvas of a new idea and a canvas of a running job are both paper, until each box has a way to be measured."),
    ("Điền kín không phải đã hiểu thị trường.", "A full canvas is not the same as understanding the market."),
)
K("fw-mece", C5, "s-47fa04eb0118", "MECE", "C5 · Khung", "S4 Không chồng, không sót", "Analytical Thinking and Structured Problem Solving using Frameworks",
    ("Các nhánh không chồng và cộng lại đủ câu hỏi", "The branches don't overlap, and together they cover the question."),
    ("Để một issue tree không đếm một đơn hai lần, cũng không quên cả một nhóm.", "So an issue tree does not count one order twice, and does not forget a whole group."),
    ("Canvas là chín ô của một mô hình. MECE là luật cắt một câu hỏi thành các nhánh.", "A canvas is nine boxes of a model. MECE is the rule for cutting one question into branches."),
    ("chồng nhau", "they overlap"), ("không chồng, đủ", "no overlap, and complete"),
    ("Mutually exclusive: một thứ chỉ nằm một nhánh. Collectively exhaustive: mọi thứ câu hỏi cần đều có nhánh.", "Mutually exclusive: a thing sits in only one branch. Collectively exhaustive: everything the question needs has a branch."),
    ("Chia form thành «kênh mới» và «TikTok» thì TikTok mới bị đếm hai lần. Quên kênh cũ thì bị sót.", "Split forms into “new channels” and “TikTok” and a new TikTok is counted twice. Forget the old channels and you have a gap."),
    ("Cắt lại đến khi một dòng chỉ có một chỗ, và không còn đám không chỗ.", "Recut until one row has one place, and no group is left without a place."),
    ("Ví dụ minh họa: câu «form đến từ đâu». Nhánh theo kênh, mỗi form một kênh, các kênh cộng đủ 100% của tuần. Thêm nhánh «khách trẻ» là chồng một kiểu khác lên, không còn MECE.", "Illustration: the question “where do forms come from”. Branches by channel, one form one channel, the channels add to 100% of the week. Adding a branch “young customers” stacks a different cut on top. It is no longer MECE."),
    [("Một tiêu chí cắt, không trộn hai tiêu chí trong một tầng.", "One cutting rule. Don't mix two rules on one level."), ("Cộng các nhánh, phải ra đúng tổng câu hỏi.", "Add the branches. They must equal the question's whole."), ("Một dòng rơi vào hai nhánh: cắt lại.", "A row that falls in two branches: cut again.")],
    ("Issue tree là cái cây của các nhánh đó. Tầng trên là câu hỏi, tầng dưới là các phần MECE. Chồng thì một đơn được cộng hai lần khi bạn tổng hợp. Sót thì một nhóm không bao giờ được nhìn. MECE không chứng minh nhánh nào là nguyên nhân. Nó chỉ giữ cho cái cây không đếm loạn.", "An issue tree is the tree of those branches. The top is the question, the level below is the MECE parts. Overlap means one order is added twice when you roll up. A gap means a group is never looked at. MECE does not prove which branch is the cause. It only keeps the tree from counting wildly."),
    ("Chồng là đếm hai lần. Sót là không nhìn.", "Overlap counts twice. A gap does not look."),
)
K("fw-7p", C5, "s-c1a8e6aa3c17", "7P", "C5 · Khung", "S5 Bảy mục kiểm", "Analytical Thinking and Structured Problem Solving using Frameworks",
    ("7P là một danh sách kiểm cho dịch vụ. Không phải một bảng xếp hạng", "The 7Ps are a checklist for a service. Not a ranking."),
    ("Để «P nào quan trọng nhất» không thành một cuộc thi không có thước.", "So “which P matters most” does not become a contest with no measure."),
    ("MECE cắt một câu hỏi. 7P nhắc bạn đừng quên một mặt của một dịch vụ.", "MECE cuts one question. The 7Ps remind you not to forget one face of a service."),
    ("bảy mục kiểm", "seven checks"), ("bảy hạng", "seven ranks"),
    ("Product, price, place, promotion, people, process, physical evidence. Bảy mục. Không có thứ tự ai thắng.", "Product, price, place, promotion, people, process, physical evidence. Seven items. No order of who wins."),
    ("Cho promotion 5 điểm và process 2 điểm là một cuộc chấm không có công thức. Hai mục không cùng đơn vị.", "Giving promotion 5 points and process 2 points is a scoring with no formula. The two items do not share a unit."),
    ("Đi qua đủ bảy mục. Đừng xếp hạng chúng.", "Walk all seven. Don't rank them."),
    ("Ví dụ minh họa: một spa. Process là các bước của một lượt. Physical evidence là phòng và phiếu. Thiếu một mục trong danh sách kiểm thì ghi thiếu. Đừng nhân điểm.", "Illustration: a spa. Process is the steps of one visit. Physical evidence is the room and the slip. A missing item on the checklist is written as missing. Don't multiply points."),
    [("Mỗi P một câu: đang có gì.", "Each P, one sentence: what is there now."), ("Thiếu thì ghi thiếu, không cho điểm 0 giả.", "If it is missing, write missing. Don't give it a fake 0."), ("Muốn so hai phương án thì so trên một thước, không so trên bảy chữ.", "If you want to compare two options, compare them on one measure, not on seven words.")],
    ("Bốn P đầu là marketing mix cổ điển. Ba P sau nhắc rằng dịch vụ có người, quy trình, và bằng chứng nhìn thấy. Danh sách này không MECE với mọi bài toán: một việc sản xuất thuần có thể không cần physical evidence theo nghĩa phòng khách. Dùng như checklist đúng việc dịch vụ, không dùng như một mô hình chấm điểm.", "The first four Ps are the classic marketing mix. The later three remind you that a service has people, a process, and evidence you can see. This list is not MECE for every problem: a pure production job may not need physical evidence in the sense of a reception room. Use it as a checklist for a service job. Don't use it as a scoring model."),
    ("Checklist không có ngôi vô địch.", "A checklist has no champion."),
)
K("fw-5c", C5, "s-c1a8e6aa3c17", "5C", "C5 · Khung", "S5 Năm phía", "Analytical Thinking and Structured Problem Solving using Frameworks",
    ("5C là năm phía cần nhìn trước khi chọn. Không phải năm slide tính từ", "The 5Cs are five sides to look at before you choose. Not five slides of adjectives."),
    ("Để một buổi «phân tích đối thủ» không chỉ là một danh sách lời khen chê.", "So a “competitor analysis” session is not only a list of praise and blame."),
    ("7P đã rà một dịch vụ của mình. 5C nhấc mắt ra các phía xung quanh.", "The 7Ps already scanned your own service. The 5Cs lift your eyes to the sides around it."),
    ("năm phía", "five sides"), ("năm tính từ", "five adjectives"),
    ("Company, customers, competitors, collaborators, climate. Năm phía. Mỗi phía một số hoặc một câu kiểm được.", "Company, customers, competitors, collaborators, climate. Five sides. Each side gets a number or a sentence you can check."),
    ("«Đối thủ mạnh» là một tính từ. «Đối thủ đang lấy cùng một từ khóa với giá thầu cao hơn» là một câu kiểm được.", "“The competitor is strong” is an adjective. “The competitor is buying the same keyword at a higher bid” is a sentence you can check."),
    ("Mỗi phía một câu có thể sai. Không có câu đó thì phía đó còn trống.", "Each side gets a sentence that could be wrong. Without that sentence, the side is still empty."),
    ("Ví dụ minh họa: customers là ai đang gửi form. Competitors là ai đang mua cùng kênh. Collaborators là đơn vị đo và đơn vị chạy ads. Climate là một quy định hoặc một mùa. Company là năng lực thật sự có trong hạn.", "Illustration: customers are who is sending forms. Competitors are who is buying the same channel. Collaborators are the measurement vendor and the ads operator. Climate is a rule or a season. Company is the capacity you actually have inside the window."),
    [("Đủ năm phía, kể cả phía bạn không thích.", "All five sides, including the side you don't like."), ("Bỏ tính từ. Để một thứ quan sát được.", "Drop the adjective. Leave something you can observe."), ("Climate không phải «thị trường khó». Nó là một điều kiện có tên.", "Climate is not “a hard market”. It is a condition with a name.")],
    ("Năm phía này là một lần quét trước khi chọn phương án, đúng chỗ C0 đã đòi các phương án có hệ quả. Nó không xếp hạng năm phía. Collaborators gồm cả đối tác làm dữ liệu: nếu họ đo sai hạt, phía company có thể đang quyết trên số sai. Đó là một phát hiện, không phải một slide.", "These five sides are a scan before you pick an option, which is where C0 already required options to have consequences. It does not rank the five sides. Collaborators include the partner who measures: if they measure the wrong grain, the company side may be deciding on a wrong number. That is a finding, not a slide."),
    ("Tính từ không lấp một phía.", "An adjective does not fill a side."),
)

K("st-shape", C5, "s-06ea6329d128", "Story shape", "C5 · Kể", "S1 Bối cảnh, chỗ kẹt, việc cần chốt", "Data Storytelling",
    ("Có cái bình thường, có chỗ kẹt, có việc cần chốt", "There is a normal, a stuck place, and a decision to close."),
    ("Để một biểu đồ không đứng một mình như một poster.", "So a chart does not stand alone like a poster."),
    ("Khung đã có câu kiểm được. Kể là thứ tự đưa câu đó cho một người.", "The frameworks already have sentences you can check. A story is the order you hand that sentence to a person."),
    ("có chỗ kẹt", "there is a stuck place"), ("chỉ có một hình", "only a picture"),
    ("Context là cái đang bình thường. Conflict là chỗ không còn bình thường. Resolution là việc bạn muốn được chốt.", "Context is what was normal. Conflict is where it is no longer normal. Resolution is the decision you want closed."),
    ("Một cột form không có chỗ kẹt thì người nghe không biết phải làm gì với cột đó.", "A bar of forms with no stuck place means the listener does not know what to do with the bar."),
    ("Ba phần, đúng một việc cần chốt.", "Three parts, exactly one decision to close."),
    ("Ví dụ minh họa: bình thường là 4% form trên click. Chỗ kẹt là tuần này 2% ở một kênh. Việc chốt là có cắt ngân sách kênh đó trong hạn đã viết hay không.", "Illustration: normal is a 4% form rate per click. The stuck place is this week at 2% on one channel. The decision to close is whether to cut that channel's budget inside the date already written."),
    [("Viết một câu bình thường.", "Write one sentence of normal."), ("Viết một câu chỗ kẹt, có số.", "Write one sentence of the stuck place, with a number."), ("Viết một câu việc cần chốt, không viết một bài học đạo đức.", "Write the decision to close. Don't write a moral.")],
    ("Ba phần này không phải mở-thân-kết của một bài văn. Resolution là một quyết định, không phải một lời «hy vọng sẽ tốt». Không có conflict thì đừng họp. Không có số trong conflict thì đó vẫn là một ý kiến, như C0 đã tách.", "These three parts are not the opening, body, and ending of an essay. The resolution is a decision, not a line that “hopes it will be better”. With no conflict, don't hold the meeting. With no number in the conflict, it is still an opinion, the split C0 already made."),
    ("Một hình không có chỗ kẹt là một poster.", "A picture with no stuck place is a poster."),
)
K("st-who", C5, "s-06ea6329d128", "Audience", "C5 · Kể", "S1 Người nghe trước", "Data Storytelling",
    ("Người nghe quyết định được gì, và họ có bao nhiêu phút", "What the listener can decide, and how many minutes they have."),
    ("Để một bản cho analyst không bị đọc nguyên si cho người chỉ có năm phút.", "So a version for an analyst is not read in full to someone who has five minutes."),
    ("Đã có ba phần của câu chuyện. Người nghe quyết định phần nào được nói.", "You have the three parts of the story. The listener decides which part gets said."),
    ("năm phút, một việc", "five minutes, one job"), ("cả sổ tay", "the whole notebook"),
    ("Audience là người trong phòng: họ quyết định được việc gì, họ đã tin gì, họ có bao lâu.", "The audience is the person in the room: what they are allowed to decide, what they already believe, and how long they have."),
    ("Một founder có năm phút không cần thấy từng bước làm sạch. Một analyst cần, nếu việc của họ là kiểm hạt.", "A founder with five minutes does not need every cleaning step. An analyst does, if their job is to check the grain."),
    ("Viết người nghe trước khi viết slide.", "Write the listener before you write the slides."),
    ("Ví dụ minh họa: người nghe chốt ngân sách, năm phút, đã tin là «TikTok rẻ». Câu chuyện phải đụng niềm tin đó bằng một tỷ lệ, không bằng mười slide định nghĩa.", "Illustration: the listener closes the budget, has five minutes, and already believes “TikTok is cheap”. The story has to touch that belief with a rate, not with ten slides of definitions."),
    [("Ai được bấm quyết định.", "Who is allowed to press the decision."), ("Họ có bao lâu.", "How long they have."), ("Họ đang tin câu gì mà số của bạn có thể làm lệch.", "What they currently believe that your number might move.")],
    ("Hai người nghe là hai câu chuyện, dù cùng một số. Nhét cả hai vào một deck là một deck không ai dùng hết. Analyst cần hạt và cách đếm. Người quyết cần câu conflict và phương án. Đừng bắt người quyết đi qua phần làm sạch để chứng minh bạn đã vất vả.", "Two listeners are two stories, even with the same number. Putting both into one deck makes a deck nobody finishes. An analyst needs the grain and the count. The person who decides needs the conflict and the options. Don't make them walk through the cleaning to prove you worked hard."),
    ("Sai người nghe thì đúng số vẫn trượt.", "The right number for the wrong listener still misses."),
)
K("st-insight", C5, "s-263dad7620de", "Insight shape", "C5 · Kể", "S2 Dạng của một nhận xét", "Data Storytelling",
    ("Nhận xét có dạng: xu hướng, khác nhau, phần, điểm lạ, hoặc đi cùng", "An insight has a shape: trend, difference, share, outlier, or together."),
    ("Để một hình tròn không được dùng cho một xu hướng.", "So a pie is not used for a trend."),
    ("Người nghe đã rõ. Dạng của nhận xét chọn hình, trước khi mở công cụ.", "The listener is clear. The shape of the insight picks the picture, before you open a tool."),
    ("xu hướng", "a trend"), ("không phải hình tròn", "not a pie"),
    ("Trend là theo thời gian. Difference là giữa các nhóm. Share là phần của một tổng. Outlier là một điểm tách đám. Together là hai thứ đi cùng nhau, chưa phải nguyên nhân.", "Trend is over time. Difference is between groups. Share is part of one whole. Outlier is a point apart from the group. Together means two things move together, which is not yet a cause."),
    ("«Form và chi cùng tăng» là together. Nó không phải «chi gây ra form». C2 đã nói đi cùng không phải nguyên nhân.", "“Forms and spend rise together” is together. It is not “spend causes forms”. C2 already said moving together is not a cause."),
    ("Gọi đúng dạng, rồi mới chọn hình đã học.", "Name the shape, then pick the picture you already learned."),
    ("Ví dụ minh họa: tám tuần một kênh là trend, dùng đường. Ba kênh một tuần là difference, dùng cột. Một tuần đủ các kênh là share. Một tuần gấp mười các tuần kia là outlier, đi kiểm, chưa kết luận.", "Illustration: eight weeks of one channel is a trend, use a line. Three channels in one week is a difference, use bars. One week of all channels is a share. One week ten times the others is an outlier: go check, don't conclude yet."),
    [("Gọi một trong năm dạng trước khi vẽ.", "Name one of the five shapes before you draw."), ("Share thì các phần phải đủ tổng. Trend thì đừng dùng pie.", "A share must have parts that add up. A trend does not get a pie."), ("Together: nói «đi cùng», đừng nói «vì».", "Together: say “move together”, don't say “because”.")],
    ("Năm dạng này chọn hình, không thay một kiểm định. Outlier có thể là một lỗi gõ, đúng như range bị một điểm cực kéo. Together là tương quan mô tả, không phải một hệ số nhân quả. Nhầm dạng là nhầm hình, và người nghe sẽ nhớ hình.", "These five shapes pick the picture. They do not replace a test. An outlier can be a typo, the same way a range is dragged by one extreme. Together is a descriptive correlation, not a causal coefficient. Get the shape wrong and you get the picture wrong, and the listener will remember the picture."),
    ("Gọi đúng dạng thì hình gần như tự chọn.", "Name the shape and the picture almost picks itself."),
)
K("st-pyramid", C5, "s-a6223b6340b0", "Answer first", "C5 · Kể", "S3 Câu trả lời trước", "Data Storytelling",
    ("Nói câu cần chốt trước. Rồi mới tới lý do", "Say the decision first. Then the reasons."),
    ("Để một bài diễn không giữ câu trả lời đến slide cuối.", "So a talk does not hold the answer until the last slide."),
    ("Dạng nhận xét đã chọn hình. Thứ tự nói là: câu chốt, các lý do, rồi bằng chứng.", "The insight shape already picked the picture. The speaking order is: the decision, the reasons, then the evidence."),
    ("câu chốt trước", "the decision first"), ("để đến slide cuối", "saved for the last slide"),
    ("Kim tự tháp: câu trả lời ở đỉnh, dưới là các lý do cùng một tầng, dưới nữa là bằng chứng của từng lý do.", "The pyramid: the answer at the top, the reasons on one level under it, the evidence for each reason under that."),
    ("Mười phút dẫn dắt rồi mới nói «nên cắt kênh» là mười phút người nghe không biết mình đang đi đâu.", "Ten minutes of buildup before “we should cut the channel” is ten minutes the listener does not know where they are going."),
    ("Câu đầu là việc cần chốt. Không phải lời chào phân tích.", "The first sentence is the decision to close. Not a hello about the analysis."),
    ("Ví dụ minh họa: «Đề nghị không tăng ngân sách kênh này trong hạn 30/11. Lý do: tỷ lệ 2% dưới ngưỡng 3%, và cách sửa trong hạn không kịp. Bằng chứng: cùng một cách đếm với tuần nền.»", "Illustration: “Do not raise this channel's budget inside the 30 Nov window. Reason: the rate is 2%, under the 3% threshold, and the fix does not fit the window. Evidence: the same count as the baseline week.”"),
    [("Câu đầu là quyết định, một câu.", "The first sentence is the decision, one sentence."), ("Mỗi lý do một dòng, không lồng vào nhau.", "Each reason is one line, not nested into the others."), ("Bằng chứng nằm dưới lý do của nó, không nằm ở một phụ lục bí mật.", "Evidence sits under its reason, not in a secret appendix.")],
    ("Pyramid principle xếp lập luận, không tạo lập luận. Nếu các lý do chồng nhau, đó là một cây chưa MECE. Nếu bằng chứng là một ý kiến, nó vẫn là ý kiến. Đừng dùng thứ tự này để giấu một mẫu số yếu ở slide 40.", "The pyramid principle orders an argument. It does not create one. If the reasons overlap, the tree is not yet MECE. If the evidence is an opinion, it is still an opinion. Don't use this order to hide a weak denominator on slide 40."),
    ("Giữ câu trả lời đến cuối là một trò bí mật, không phải một phân tích.", "Holding the answer until the end is a mystery, not an analysis."),
)
K("st-one", C5, "s-c58c873baba3", "One message", "C5 · Kể", "S4 Một thông điệp", "Data Storytelling",
    ("Hai tiêu đề là hai câu chuyện. Tách ra", "Two headlines are two stories. Split them."),
    ("Để một slide không phải gánh cả một quý.", "So one slide does not have to carry a whole quarter."),
    ("Câu chốt đã đứng trước. Luật này là đừng nhét thêm một câu chốt thứ hai vào cùng trang.", "The decision already stands first. This rule is: don't put a second decision on the same page."),
    ("một thông điệp", "one message"), ("hai tiêu đề", "two headlines"),
    ("Một trang một thông điệp. Nếu bạn cần chữ «và» để nối hai quyết định, đó là hai trang.", "One page, one message. If you need the word “and” to join two decisions, that is two pages."),
    ("«Cắt kênh này và làm lại thương hiệu» là hai việc. Một slide làm cả hai thì không việc nào được chốt.", "“Cut this channel and redo the brand” is two jobs. One slide that does both closes neither."),
    ("Tách đến khi mỗi trang chỉ xin một việc.", "Split until each page asks for one job."),
    ("Ví dụ minh họa: trang 1 chỉ ngân sách kênh trong hạn này. Trang 2, nếu còn giờ, mới là brand. Người nghe năm phút thì chỉ nhận trang 1.", "Illustration: page 1 is only this window's channel budget. Page 2, if there is time, is the brand. A listener with five minutes only gets page 1."),
    [("Đọc tiêu đề. Thấy hai động từ quyết định thì tách.", "Read the headline. Two decision verbs means you split."), ("Một hình phụ không được mang một câu thứ hai.", "A secondary picture does not get to carry a second sentence."), ("Hết giờ thì câu thứ hai không được nói tạm.", "If time is gone, the second sentence does not get a quick mention.")],
    ("Một thông điệp không phải một slogan. Nó là một quyết định cộng các lý do của quyết định đó. Nhét một insight dạng trend vào một trang đang xin một difference là hai dạng, hai câu. Người nghe nhớ hình cuối, thường là hình rối.", "One message is not a slogan. It is one decision plus the reasons for that decision. Putting a trend insight on a page that is asking for a difference is two shapes, two sentences. The listener remembers the last picture, which is usually the messy one."),
    ("Thêm một chữ «và» là thêm một cuộc họp.", "Adding the word “and” adds another meeting."),
)
K("st-board", C5, "s-c58c873baba3", "Storyboard", "C5 · Kể", "S4 Thứ tự các trang", "Data Storytelling",
    ("Storyboard là thứ tự các câu. Không phải bảng màu", "A storyboard is the order of the sentences. Not a color palette."),
    ("Để việc chỉnh màu không được tính là đã kể xong.", "So adjusting colors does not count as having told the story."),
    ("Đã một trang một thông điệp. Storyboard là xếp các trang đó thành một đường đi.", "You already have one message per page. A storyboard is those pages in a path."),
    ("thứ tự câu", "the order of sentences"), ("một bảng màu", "a color palette"),
    ("Mỗi khung là một câu, một hình, và việc người nghe làm với khung đó. Đổi thứ tự là đổi lập luận.", "Each frame is one sentence, one picture, and what the listener does with that frame. Change the order and you change the argument."),
    ("Chọn xong màu mà chưa có thứ tự các câu thì chưa có chuyện. Chỉ có một tập slide.", "Pick the colors with no order of sentences and you have no story. You have a pile of slides."),
    ("Xếp các câu trước. Màu để sau, và chỉ để các câu đọc được.", "Order the sentences first. Color comes later, and only so the sentences can be read."),
    ("Ví dụ minh họa: khung 1 là câu chốt, khung 2 là tỷ lệ so với ngưỡng, khung 3 là phương án trong hạn. Bỏ khung 2 thì khung 3 mất căn. Đổi màu xanh của cột không vá được lỗ đó.", "Illustration: frame 1 is the decision, frame 2 is the rate against the threshold, frame 3 is the option inside the window. Drop frame 2 and frame 3 loses its ground. Changing the blue of a bar does not patch that hole."),
    [("Mỗi khung một câu viết ra, không phải một tiêu đề «phân tích».", "Each frame has a sentence written out, not a title that says “analysis”."), ("Đọc thứ tự mà thiếu một khung vẫn đứng được thì khung thừa nên xét lại.", "If the order still stands when a frame is removed, that frame should be reconsidered."), ("Màu chỉ sau khi thứ tự đã đọc được bằng chữ.", "Color only after the order can be read as text.")],
    ("Storyboard của một data story giống story của Tableau: một chuỗi có chủ đích. Nó không phải moodboard. Một khung không có việc cho người nghe là một khung trang trí, đúng luật «decoration không phải phân tích» đã nói ở Tableau.", "The storyboard of a data story is like a Tableau story: a deliberate sequence. It is not a moodboard. A frame with nothing for the listener to do is a decoration frame, the same law as “decoration is not analysis” from the Tableau cards."),
    ("Chưa xếp được các câu bằng chữ thì đừng mở bảng màu.", "If you cannot order the sentences in words, don't open the palette."),
)

# C6 OR
K("or-obj", C6, "s-e7dfa00a4a1f", "Objective", "C6 · Tối ưu", "S1 Cái cần cực đại", "Operations Research using Excel",
    ("Mục tiêu không phải biến quyết định", "The objective is not the decision variable."),
    ("Để doanh thu không vừa là cái cần cực đại vừa là cái bạn được phép gõ.", "So revenue is not both the thing to maximize and the thing you are allowed to type."),
    ("Các khóa trước đã có một thước của quyết định. Tối ưu là khi thước đó là một hàm của các lựa chọn, trong các giới hạn.", "Earlier courses already have a measure of the decision. Optimization is when that measure is a function of the choices, inside limits."),
    ("cái cần cực đại", "what you maximize"), ("cái bạn được chọn", "what you are allowed to choose"),
    ("Objective là hàm cần cực đại hoặc cực tiểu. Decision variable là những số bạn được chọn. Chúng không phải cùng một ô.", "The objective is the function to maximize or minimize. Decision variables are the numbers you are allowed to choose. They are not the same cell."),
    ("«Tối đa doanh thu» mà ô doanh thu lại là ô bạn gõ tay thì bạn đang gõ kết quả, không đang chọn.", "“Maximize revenue” while the revenue cell is a cell you type means you are typing the result, not choosing."),
    ("Một ô cho hàm mục tiêu, các ô khác cho biến. Đừng trùng.", "One cell for the objective function, other cells for the variables. Don't overlap them."),
    ("Ví dụ minh họa: chọn số suất quảng cáo của từng kênh. Đó là biến. Doanh thu là công thức của các suất đó. Bạn không gõ doanh thu. Số là ví dụ cấu trúc, không phải một kết quả solver.", "Illustration: choose the number of ad slots per channel. Those are the variables. Revenue is a formula of those slots. You don't type the revenue. The numbers illustrate the structure, not a solver result."),
    [("Viết hàm mục tiêu bằng một câu: cực đại cái gì, hoặc cực tiểu cái gì.", "Write the objective in one sentence: maximize what, or minimize what."), ("Liệt kê các số bạn thực sự được chọn.", "List the numbers you are actually allowed to choose."), ("Nếu một «biến» chỉ là công thức của biến khác, nó không phải biến.", "If a “variable” is only a formula of other variables, it is not a variable.")],
    ("Nhầm objective với decision variable thì bài toán không còn gì để giải: bạn tự điền đáp án. Một ràng buộc cũng không phải objective. «Không vượt ngân sách» là giới hạn. «Lợi nhuận» mới có thể là mục tiêu. Cả hai cùng một ô là một mô hình gãy.", "Mix up the objective and the decision variables and there is nothing left to solve: you typed the answer yourself. A constraint is also not the objective. “Don't exceed the budget” is a limit. “Profit” might be the objective. Both in one cell is a broken model."),
    ("Gõ được vào ô mục tiêu là mô hình chưa thành.", "If you can type in the objective cell, the model is not built yet."),
)
K("or-con", C6, "s-a69a7c2d9dfb", "Constraints", "C6 · Tối ưu", "S2 Giới hạn", "Operations Research using Excel",
    ("Một giới hạn là một nguồn không được tiêu hai lần", "A constraint is a resource you cannot spend twice."),
    ("Để ngân sách một tháng không bị các kênh cộng vượt mà solver vẫn «tối ưu».", "So one month's budget is not exceeded by the channels while the solver still says “optimal”."),
    ("Đã tách mục tiêu và biến. Giới hạn là những bất đẳng thức các biến phải tôn trọng.", "The objective and the variables are split. Constraints are the inequalities the variables must respect."),
    ("tiêu một lần", "spent once"), ("cộng vượt", "added past the limit"),
    ("Constraint là một bất đẳng thức trên các biến. Tổng sử dụng không vượt quá lượng có, trừ khi bạn viết một giới hạn khác và chịu nó.", "A constraint is an inequality on the variables. Total use does not exceed what you have, unless you wrote a different limit and you accept it."),
    ("Ba kênh mỗi kênh xin cả ngân sách tháng thì không phải ba phương án cùng khả thi. Đó là một giới hạn bị viết thiếu.", "Three channels each asking for the whole month's budget are not three feasible options together. That is a constraint you forgot to write."),
    ("Mỗi nguồn một bất đẳng thức. Đọc lại xem tổng có thể vượt không.", "Each resource gets one inequality. Read it back and see whether the total can still exceed it."),
    ("Ví dụ minh họa: ngân sách 100. Các suất nhân đơn giá, tổng ≤ 100. Quên dòng này thì «tối ưu» cứ tăng suất mãi. Số 100 là ví dụ cấu trúc.", "Illustration: budget 100. Slots times price, the sum ≤ 100. Forget this row and the “optimum” just keeps raising slots. The 100 illustrates the structure."),
    [("Mỗi nguồn khan một dòng ≤ hoặc ≥.", "Each scarce resource gets one ≤ or ≥ row."), ("Kiểm một phương án cực đoan: nó có vi phạm dòng đó không.", "Check an extreme option: does it violate that row."), ("Đừng viết mục tiêu vào dòng giới hạn.", "Don't write the objective on the constraint row.")],
    ("Một giới hạn viết sai chiều là một bài toán khác. ≤ thành ≥ có thể làm bài không còn phương án, hoặc thành không có biên. Infeasibility là các giới hạn cãi nhau, không phải solver hỏng. Unbounded là mục tiêu chạy mãi vì thiếu một giới hạn. Cả hai là lỗi mô hình, không phải một kết quả kinh doanh.", "A constraint with the wrong direction is a different problem. Turning ≤ into ≥ can leave no feasible option, or it can remove the boundary. Infeasibility means the constraints argue with each other, not that the solver is broken. Unbounded means the objective runs forever because a limit is missing. Both are model errors, not a business result."),
    ("Thiếu một giới hạn thì «tối ưu» là một cái hố không đáy.", "Miss a constraint and the “optimum” is a hole with no bottom."),
)
K("or-sens", C6, "s-a69a7c2d9dfb", "Sensitivity", "C6 · Tối ưu", "S2 Độ nhạy", "Operations Research using Excel",
    ("Độ nhạy chỉ đúng chừng nào vẫn là góc đó", "Sensitivity holds only while it is still that corner."),
    ("Để một shadow price không được dùng khi bạn đã nhảy sang một phương án khác hẳn.", "So a shadow price is not used once you have jumped to a completely different option."),
    ("Giới hạn đã có. Sensitivity hỏi: nới một giới hạn một chút thì mục tiêu đổi bao nhiêu, khi góc đang chọn chưa đổi.", "The constraints exist. Sensitivity asks: loosen one limit a little and how much does the objective move, while the chosen corner has not changed."),
    ("còn đúng góc này", "still this corner"), ("đã sang góc khác", "already another corner"),
    ("Shadow price là mức mục tiêu đổi khi nới một ràng buộc một đơn vị, trong khoảng góc hiện tại còn là góc tối ưu.", "The shadow price is how the objective moves when you loosen one constraint by one unit, inside the range where the current corner stays optimal."),
    ("Nới ngân sách thêm một ít mà góc các kênh vẫn vậy thì giá bóng dùng được. Nới đến mức một kênh bị tắt hẳn thì giá bóng cũ hết hạn.", "Loosen the budget a little and the channel corner stays: the shadow price still applies. Loosen it until a channel turns off entirely and the old shadow price has expired."),
    ("Đọc khoảng cho phép. Ngoài khoảng đó thì giải lại.", "Read the allowable range. Outside it, solve again."),
    ("Ví dụ minh họa: giá bóng của ngân sách là 0,2 trong khoảng cộng thêm không quá 10. Cộng 30 là ra ngoài khoảng. Đừng nhân 30 × 0,2 rồi đưa vào brief. Số là ví dụ cấu trúc.", "Illustration: the budget's shadow price is 0.2 within an extra 10. Adding 30 is outside the range. Don't multiply 30 × 0.2 and put it in the brief. The numbers illustrate the structure."),
    [("Chỉ đọc giá bóng của ràng buộc đang chặt.", "Only read the shadow price of a constraint that is tight."), ("Nhìn allowable increase và decrease.", "Look at the allowable increase and decrease."), ("Ra ngoài khoảng: chạy solver lại, đừng nhân tiếp.", "Outside the range: run the solver again. Don't keep multiplying.")],
    ("Báo cáo độ nhạy của một bài tuyến tính nói về góc đang chọn. Reduced cost nói một biến đang bằng 0 sẽ cần lợi thế thêm bao nhiêu thì mới được vào góc. Đổi một hệ số vượt khoảng thì góc đổi, và các giá bóng đổi theo. Đây không phải một đạo hàm dùng mãi. Và nó không áp cho một bài phi tuyến theo cùng một tờ báo cáo.", "The sensitivity report of a linear problem talks about the corner that is selected. Reduced cost says how much extra advantage a variable currently at 0 would need before it enters the corner. Change a coefficient past its range and the corner changes, and the shadow prices change with it. This is not a derivative you can use forever. And it does not apply to a nonlinear problem on the same report sheet."),
    ("Hết khoảng là hết giá bóng đó.", "Past the range, that shadow price is over."),
)
K("or-solv", C6, "s-9b7619194d29", "Solver corner", "C6 · Tối ưu", "S3 Góc", "Operations Research using Excel",
    ("Bài tuyến tính tìm một góc. Bài cong có thể dừng ở một chỗ lõm cục bộ", "A linear problem finds a corner. A curved problem can stop in a local dent."),
    ("Để một lần solver «xong» trên bài cong không bị gọi là tối ưu toàn cục.", "So a solver that “finished” on a curved problem is not called a global optimum."),
    ("Độ nhạy đã giả sử một góc tuyến tính. Solver là cái đi tìm điểm đó, và chỉ chắc một góc khi bài là tuyến tính.", "Sensitivity already assumed a linear corner. The solver is what goes looking for that point, and it is only sure of a corner when the problem is linear."),
    ("tìm một góc", "finds a corner"), ("dừng ở một lõm", "stops in a dent"),
    ("Với ràng buộc tuyến tính và mục tiêu tuyến tính, phương án tối ưu nằm ở một đỉnh. Phi tuyến có thể có nhiều chỗ lõm. Solver dừng ở một chỗ không có nghĩa hết chỗ khác tốt hơn.", "With linear constraints and a linear objective, an optimum sits at a vertex. A nonlinear problem can have many dents. A solver stopping does not mean there is no better place."),
    ("Một hàm lãi cong theo giá. Solver từ một giá xuất phát có thể dừng ở một đỉnh cục bộ. Đổi điểm xuất phát ra một số khác.", "A profit function curved in price. A solver from one starting price can stop at a local peak. Start from another price and you can get another number."),
    ("Bài tuyến tính: tin một góc, rồi đọc độ nhạy trong khoảng. Bài cong: thử nhiều điểm xuất phát, đừng gọi là toàn cục.", "A linear problem: trust a corner, then read sensitivity inside the range. A curved problem: try several starts, and don't call it global."),
    ("Ví dụ minh họa: hai biến, các ràng buộc là các đường thẳng, vùng là một đa giác. Solver đứng ở một đỉnh. Thêm một bình phương vào mục tiêu thì đa giác không còn là nơi «đỉnh là đủ».", "Illustration: two variables, constraints as straight lines, the region is a polygon. The solver stands on a vertex. Add a square to the objective and the polygon is no longer a place where “a vertex is enough”."),
    [("Nói bài này tuyến tính hay không.", "Say whether this problem is linear."), ("Tuyến tính: nhìn đỉnh, rồi khoảng độ nhạy.", "Linear: look at the vertex, then the sensitivity range."), ("Không tuyến tính: chạy từ vài điểm xuất phát. Khác nhau thì chưa có một đỉnh toàn cục.", "Not linear: run from several starting points. If they differ, you do not have one global peak.")],
    ("Simplex và các phương pháp cho LP đi trên cạnh tới một đỉnh. GRG và các phương pháp phi tuyến đi theo dốc cục bộ. Chúng có thể dừng vì bước quá nhỏ, không phải vì đã hết phương án tốt hơn. Local optimum không phải global optimum. Đừng lấy báo cáo độ nhạy LP dán lên một bài có bình phương.", "Simplex and other LP methods walk edges to a vertex. GRG and other nonlinear methods follow a local slope. They can stop because the step got small, not because no better option remains. A local optimum is not a global optimum. Don't paste an LP sensitivity report onto a problem that has a square in it."),
    ("«Solver xong» trên một bài cong là «dừng», không phải «hết chỗ tốt hơn».", "“Solver finished” on a curved problem means “it stopped”, not “there is nothing better”."),
)
K("or-sheet", C6, "s-c0c015993686", "The sheet is the model", "C6 · Tối ưu", "S4 Ô nào solver đọc", "Operations Research using Excel",
    ("Solver chỉ đọc các ô bạn chỉ. Một số gõ ở ngoài không phải giới hạn", "The solver only reads the cells you point at. A number typed elsewhere is not a constraint."),
    ("Để một ghi chú «nhớ để dành 10%» không được tính là một ràng buộc.", "So a note that says “remember to keep 10%” does not count as a constraint."),
    ("Đã biết góc và độ nhạy. Trên Excel, những thứ đó chỉ tồn tại nếu từng ô được trỏ đúng.", "You know about corners and sensitivity. In Excel those exist only if each cell is pointed at correctly."),
    ("ô được trỏ", "a cell that is pointed at"), ("một ghi chú", "a note"),
    ("Ô mục tiêu, các ô biến, từng dòng giới hạn: solver không đọc phần còn lại của sheet.", "The objective cell, the variable cells, each constraint row: the solver does not read the rest of the sheet."),
    ("Bạn ghi «tối đa 40 suất» ở một ô chữ bên cạnh. Không đưa ô đó vào constraints thì 40 không tồn tại với solver.", "You type “at most 40 slots” in a text cell nearby. If that cell is not in the constraints, 40 does not exist for the solver."),
    ("Mọi giới hạn là một ô công thức được khai. Không phải một comment.", "Every limit is a formula cell you declared. Not a comment."),
    ("Ví dụ minh họa: biến là B2:B4, mục tiêu là B6, giới hạn ngân sách là B8 ≤ B9. Ô B12 ghi một lời nhắc thì không tham gia. Số là ví dụ cấu trúc.", "Illustration: variables are B2:B4, the objective is B6, the budget limit is B8 ≤ B9. Cell B12 with a reminder does not take part. The addresses illustrate the structure."),
    [("Liệt kê đúng các ô biến, không gồm ô công thức.", "List the variable cells exactly, and don't include formula cells."), ("Mỗi giới hạn một dòng trong cửa sổ solver.", "Each limit is one row in the solver window."), ("Đổi sheet mà không cập nhật vùng ô là giải một bài khác.", "Change the sheet without updating the cell ranges and you are solving a different problem.")],
    ("Một ô biến phải là số solver được sửa. Trỏ nhầm vào ô công thức thì hoặc lỗi, hoặc bạn tưởng đang chọn một thứ thực ra đã bị công thức giữ. Tuyên bố linearity mà mô hình có IF hoặc có phép nhân hai biến là một báo cáo độ nhạy không còn đúng nghĩa. Giữ mô hình trên một vùng nhỏ, đọc được, đúng như macro không được phép giấu quyết định.", "A variable cell has to be a number the solver is allowed to change. Point at a formula cell by mistake and you either get an error, or you think you are choosing something a formula is already holding. Declare linearity while the model has an IF or a product of two variables and the sensitivity report no longer means what it says. Keep the model in a small range you can read, the same way a macro is not allowed to hide a decision."),
    ("Không được trỏ thì không phải một giới hạn.", "If it is not pointed at, it is not a constraint."),
)

# GenAI
K("ga-next", C6, "s-48015ecb822d", "Next token", "C6 · GenAI", "S1 Token kế tiếp", "Introduction to GenAI and Working with OpenAI APIs",
    ("Token kế tiếp không phải một cơ sở dữ liệu", "The next token is not a database."),
    ("Để một câu trả lời trôi chảy không bị dùng như một bảng giá.", "So a fluent answer is not used as a price list."),
    ("Các khóa trước số đến từ một hạt đếm được. GenAI sinh token kế tiếp của một đoạn chữ.", "Earlier courses got numbers from a grain you can count. GenAI produces the next token of a piece of text."),
    ("chữ kế tiếp", "the next text"), ("không tra bảng", "not a table lookup"),
    ("Mô hình chấm các mảnh chữ có thể đứng tiếp theo. Nó không mở file giá của bạn trừ khi đoạn chữ đó đang nằm trong prompt.", "The model scores pieces of text that might come next. It does not open your price file unless that text is already in the prompt."),
    ("Hỏi «giá gói tháng này» mà không đưa bảng giá thì câu trả lời là một câu hợp lệ, không phải một dòng trong bảng.", "Ask “this month's package price” without giving the price table and the answer is a grammatical sentence, not a row in the table."),
    ("Muốn một số từ file thì đưa file, hoặc đừng hỏi mô hình.", "If you want a number from a file, give the file, or don't ask the model."),
    ("Ví dụ minh họa: không có bảng giá trong prompt. Mô hình vẫn viết được một số tiền. Số đó không phải số của công ty. Đừng đem đi thu.", "Illustration: no price table in the prompt. The model can still write an amount. That amount is not the company's number. Don't collect it."),
    [("Hỏi: số này đang ở đâu trong prompt.", "Ask: where in the prompt is this number."), ("Không ở đâu: đừng dùng số mô hình vừa viết.", "Nowhere: don't use the number the model just wrote."), ("Việc cần một bảng thì làm một câu SQL, không làm một đoạn chat.", "A job that needs a table is a SQL query, not a chat paragraph.")],
    ("Token là mảnh mô hình dùng để viết, không phải một từ từ điển. «Kế tiếp» là một phân phối trên các mảnh, rồi một cách chọn. Chọn xong một mảnh thì mảnh đó trở thành quá khứ và được chấm tiếp. Không bước nào tra khóa chính. Đây không phải VLOOKUP.", "A token is a piece the model uses to write, not a dictionary word. “Next” is a distribution over pieces, then a way of choosing. Once a piece is chosen it becomes the past and the scoring continues. No step looks up a primary key. This is not VLOOKUP."),
    ("Viết được một số không có nghĩa là đã tra được số.", "Being able to write a number does not mean the number was looked up."),
)
K("ga-vs", C6, "s-48015ecb822d", "ML and GenAI", "C6 · GenAI", "S1 Hai việc khác nhau", "Introduction to GenAI and Working with OpenAI APIs",
    ("Học máy đoán một cột. GenAI nối một đoạn chữ", "Machine learning predicts a column. GenAI continues a piece of text."),
    ("Để một mô hình churn không bị gọi là một chatbot, và ngược lại.", "So a churn model is not called a chatbot, and the reverse."),
    ("Token kế tiếp đã là việc của GenAI. C3 là một dòng ra một dự đoán có thước.", "Next-token was the GenAI job. C3 is one row becoming a prediction with a measure."),
    ("đoán một cột", "predict a column"), ("nối chữ", "continue text"),
    ("Một model churn trả một xác suất trên một dòng khách. Một mô hình sinh trả một đoạn chữ. Thước của hai việc khác nhau.", "A churn model returns a probability on one customer row. A generative model returns a piece of text. The measures of the two jobs differ."),
    ("Accuracy của một lớp hiếm không phải thước của một đoạn chat. Một đoạn chat hay không phải một AUC.", "Accuracy on a rare class is not the measure of a chat paragraph. A pleasant paragraph is not an AUC."),
    ("Gọi đúng việc trước khi chọn thước.", "Name the job before you pick the measure."),
    ("Ví dụ minh họa: «khách này có rời không» là một cột, có nhãn, có tập chấm. «Viết một tin nhắn» là một đoạn chữ, không có một ô đúng duy nhất.", "Illustration: “will this customer leave” is a column, with labels and a scoring set. “Write a message” is a piece of text, with no single correct cell."),
    [("Có nhãn trên từng dòng và một thước đã viết: đó là hướng C3 và C4.", "Labels on each row and a measure you wrote: that is the C3 and C4 direction."), ("Cần một đoạn chữ: đó là GenAI, và đừng báo accuracy.", "If you need a piece of text: that is GenAI, and don't report accuracy."), ("Đừng để một đoạn chữ điền vào một cột quyết định.", "Don't let a piece of text fill a decision column.")],
    ("Cùng một họ mô hình lớn có thể được huấn luyện theo nhiều cách. Việc của bạn không phải đoán kiến trúc. Việc của bạn là nói đầu ra là một xác suất có tập chấm, hay một đoạn chữ không có ô đúng duy nhất. Trộn thước là brief sai, đúng kiểu accuracy 92% trên một lớp hiếm.", "The same family of large models can be trained in several ways. Your job is not to guess the architecture. Your job is to say whether the output is a probability with a scoring set, or a piece of text with no single correct cell. Mixing the measures is a bad brief, the same kind of mistake as 92% accuracy on a rare class."),
    ("Một đoạn văn không phải một xác suất.", "A paragraph is not a probability."),
)
K("ga-stack", C6, "s-38f28fdcbd4f", "Stack", "C6 · GenAI", "S2 Ba tầng", "Introduction to GenAI and Working with OpenAI APIs",
    ("Mô hình, dữ liệu, và sản phẩm là ba tầng", "The model, the data, and the product are three layers."),
    ("Để một lần đổi prompt không bị gọi là đã đổi mô hình.", "So changing a prompt is not called changing the model."),
    ("Đã tách đoán cột và nối chữ. Trong việc nối chữ vẫn có ba tầng đừng gọi nhầm tên.", "Predicting a column and continuing text are already split. Inside the text job there are still three layers whose names you should not mix."),
    ("đổi dữ liệu đưa vào", "change the data you pass"), ("đổi trọng số", "change the weights"),
    ("Model là trọng số. Data là cái bạn đưa vào lần gọi này. Product là việc người dùng làm với câu trả lời.", "The model is the weights. The data is what you pass on this call. The product is what the user does with the answer."),
    ("Sửa một câu trong prompt là sửa data của lần gọi. Không phải fine-tune. Không phải một sản phẩm mới.", "Editing a sentence in the prompt edits the data of that call. It is not a fine-tune. It is not a new product."),
    ("Nói bạn đang đụng tầng nào.", "Say which layer you are touching."),
    ("Ví dụ minh họa: cùng một model. Lần gọi có dán chính sách đổi trả thì câu chữ khác lần gọi không dán. Sản phẩm vẫn chưa có nút «đặt lịch» thì người dùng vẫn chỉ có một đoạn chữ.", "Illustration: the same model. A call that pastes the return policy writes differently from a call that does not. If the product still has no “book” button, the user still only has a paragraph."),
    [("Đổi chữ prompt: gọi là đổi đầu vào.", "Changing the prompt text: call it changing the input."), ("Đổi trọng số: gọi là fine-tune hoặc một model khác, và nói ai chịu.", "Changing the weights: call it a fine-tune or a different model, and say who owns it."), ("Một nút cho người dùng là tầng sản phẩm, không nằm trong mô hình.", "A button for the user is the product layer. It is not inside the model.")],
    ("Ba tầng hỏng độc lập. Model viết trôi mà data thiếu chính sách thì câu trôi vẫn sai chính sách. Data đủ mà sản phẩm không cho người dùng kiểm lại nguồn thì họ vẫn làm theo một đoạn chữ. Đừng gói cả ba thành «AI» rồi giao cho một người sửa prompt.", "The three layers fail independently. A fluent model with the policy missing from the data still writes a fluent wrong policy. Enough data, but a product that does not let the user check the source, and they still follow a paragraph. Don't wrap all three as “AI” and hand them to one person who edits prompts."),
    ("Sửa prompt không phải sửa não của mô hình.", "Editing the prompt is not editing the model's brain."),
)
K("ga-use", C6, "s-697cf590785b", "Use case", "C6 · GenAI", "S3 Cái giá của một lần sai", "Introduction to GenAI and Working with OpenAI APIs",
    ("Một use case là một việc, kèm cái giá khi chữ sai", "A use case is a job, plus the cost when the text is wrong."),
    ("Để một demo hay không thành một quyết định đưa vào vận hành.", "So a nice demo does not become a decision to put it into operation."),
    ("Ba tầng đã có tên. Use case là việc của tầng sản phẩm: ai làm gì, và sai thì mất gì.", "The three layers have names. A use case is the product layer's job: who does what, and what is lost if it is wrong."),
    ("có giá của một lần sai", "there is a cost of being wrong"), ("một demo", "a demo"),
    ("Một việc GenAI cần một người chịu, một đầu ra, và một cách xử lý khi đầu ra sai. Demo không có ba thứ đó.", "A GenAI job needs an owner, an output, and a way to handle a wrong output. A demo has none of the three."),
    ("Một đoạn chat viết được bài quảng cáo. Đưa nhầm giá vào bài đó thì cái giá là tiền và lòng tin, không phải «chữ chưa hay».", "A chat can write an ad. Put the wrong price in that ad and the cost is money and trust, not “the prose is not nice yet”."),
    ("Viết cái giá của một lần sai trước khi đưa vào việc.", "Write the cost of one wrong answer before you put it into the job."),
    ("Ví dụ minh họa: nháp một tiêu đề cho người marketing sửa là một việc, giá của một lần sai thấp. Tự gửi giá cho khách là một việc khác, giá của một lần sai là một hợp đồng. Đừng dùng cùng một nút.", "Illustration: drafting a headline for a marketer to edit is one job, and the cost of being wrong is low. Sending a price to a customer by itself is another job, and the cost of being wrong is a contract. Don't use the same button."),
    [("Ai bấm gửi, ai chịu.", "Who presses send, and who owns it."), ("Sai một lần thì mất gì.", "What one wrong time costs."), ("Chưa có người sửa mà giá của sai là một hợp đồng: đừng tự gửi.", "If nobody reviews it and the cost of being wrong is a contract, don't send it alone.")],
    ("Use case không phải một ngành hàng trên slide. «Dùng cho marketing» không nói được sai thì ai mất gì. Cùng luật deployment của CRISP: có chủ, có việc lặp, có lúc nào thì dừng. Một demo trong phòng không phải deployment.", "A use case is not an industry on a slide. “Use it for marketing” does not say who loses what if it is wrong. Same deployment law as CRISP: an owner, a repeated job, and a time to stop. A demo in a room is not a deployment."),
    ("Hay trong phòng không phải rẻ khi sai.", "Nice in the room is not cheap when it is wrong."),
)
K("ga-chat", C6, "s-6162e86bf01d", "Messages", "C6 · GenAI", "S5 Đoạn hội thoại", "Introduction to GenAI and Working with OpenAI APIs",
    ("Các message là đoạn chữ lần gọi này được thấy. Không phải trí nhớ về thế giới", "The messages are the text this call can see. Not a memory of the world."),
    ("Để một câu «hôm trước tôi đã nói giá» không còn hiệu lực nếu lần gọi này không gửi câu đó.", "So “I told you the price last time” does not count if this call does not send that sentence."),
    ("Use case đã có cái giá của sai. API là chỗ cái sai đó đi vào qua đúng những message bạn gửi.", "The use case already has the cost of being wrong. The API is where that wrongness enters, through the exact messages you send."),
    ("chỉ thấy message này", "it only sees these messages"), ("không nhớ hộ", "it does not remember for you"),
    ("Một lần gọi nhận một danh sách message: system, user, và có thể là các lượt trước bạn tự gửi lại. Không gửi lại thì không còn.", "One call receives a list of messages: system, user, and maybe earlier turns you send again yourself. If you don't send them again, they are gone."),
    ("Hôm qua bạn nói giá trong một phiên khác. Hôm nay một request mới không kèm câu đó thì mô hình không «nhớ giá hôm qua».", "Yesterday you said a price in another session. Today a new request without that sentence means the model does not “remember yesterday's price”."),
    ("Muốn nó thấy thì để trong message của lần gọi này.", "If you want it seen, put it in this call's messages."),
    ("Ví dụ minh họa: system nói «chỉ dùng bảng giá đính kèm». User dán bảng. Thiếu một trong hai thì lần gọi đó không có đủ. Ứng dụng phải gửi lại, mô hình không giữ hộ.", "Illustration: the system says “use only the attached price table”. The user pastes the table. Miss either one and that call does not have enough. The application has to send it again. The model does not keep it for you."),
    [("Coi log của đúng request, không nhớ bằng cảm giác.", "Read the log of that exact request. Don't remember by feel."), ("Lượt trước mà sản phẩm cần thì sản phẩm phải gửi lại.", "If the product needs the previous turn, the product has to send it again."), ("Đừng nhét một sự thật chỉ có trong đầu bạn.", "Don't put in a fact that exists only in your head.")],
    ("Role system không phải một cái khóa pháp lý. Nó là một message đứng trước. Model vẫn có thể viết lệch nó. History do ứng dụng của bạn lưu, không do một trí nhớ chung của mọi khách. Dán nhầm history của khách A vào request của khách B là một lỗi sản phẩm, không phải một tính năng của mô hình.", "A system role is not a legal lock. It is a message that comes first. The model can still write against it. History is stored by your application, not by a shared memory of every customer. Pasting customer A's history into customer B's request is a product bug, not a feature of the model."),
    ("Không gửi thì không thấy. Kể cả hôm qua đã nói.", "If you don't send it, it is not seen. Even if you said it yesterday."),
)
K("ga-temp", C6, "s-6162e86bf01d", "Temperature", "C6 · GenAI", "S5 Độ đa dạng", "Introduction to GenAI and Working with OpenAI APIs",
    ("Temperature đổi độ đa dạng. Không đổi sự thật", "Temperature changes variety. It does not change the truth."),
    ("Để một temperature thấp không bị gọi là «chế độ chính xác».", "So a low temperature is not called “accuracy mode”."),
    ("Message đã là toàn bộ cái mô hình thấy. Temperature chỉ đổi cách chọn token trong các token đang hợp lệ với mô hình.", "The messages are already everything the model sees. Temperature only changes how a token is picked among the tokens the model already finds plausible."),
    ("đa dạng hơn", "more variety"), ("không đúng hơn", "not more true"),
    ("Temperature cao: các mảnh ít điểm hơn vẫn có cơ hội được chọn. Thấp: nghiêng về mảnh điểm cao. Không mảnh nào trở thành một dòng trong bảng giá nhờ nút này.", "High temperature: lower-scoring pieces still get a chance. Low: it leans toward the high-scoring piece. No piece becomes a row in the price table because of this knob."),
    ("Hạ temperature mà bảng giá không nằm trong message thì câu vẫn có thể viết sai giá, chỉ ít bay hơn.", "Lower the temperature while the price table is not in the messages and the sentence can still write the wrong price. It just wanders less."),
    ("Chỉnh temperature khi cần đều hoặc cần nhiều phương án chữ. Đừng chỉnh để «cho đúng».", "Change temperature when you need steadiness or several wordings. Don't change it to “make it true”."),
    ("Ví dụ minh họa: cùng một prompt thiếu giá. Chạy năm lần temperature cao ra năm số khác nhau. Temperature thấp ra một số lặp lại. Số lặp lại vẫn không phải giá công ty.", "Illustration: the same prompt, missing the price. Five runs at high temperature give five different amounts. Low temperature repeats one amount. The repeated amount is still not the company's price."),
    [("Thiếu nguồn thì đừng hy vọng nút này vá.", "If the source is missing, don't hope this knob patches it."), ("Cần nhiều cách diễn đạt: tăng có chủ đích.", "If you need several phrasings, raise it on purpose."), ("Cần một định dạng đều: hạ, rồi vẫn kiểm nguồn.", "If you need a steady format, lower it, and still check the source.")],
    ("Temperature không phải xác suất câu đúng. Nó là một tham số của cách lấy mẫu. Top-p cũng là một cách cắt đuôi của phân phối, cùng họ, cũng không thêm sự thật. Một câu lặp lại năm lần ở temperature 0 là một câu ổn định, không phải một câu đã được kiểm.", "Temperature is not the probability the sentence is true. It is a parameter of how you sample. Top-p is another way to cut the tail of the distribution, same family, and it also adds no truth. A sentence that repeats five times at temperature 0 is a stable sentence, not a checked one."),
    ("Ổn định không phải đúng.", "Stable is not the same as true."),
)
K("ga-tok", C6, "s-6162e86bf01d", "Tokens and cost", "C6 · GenAI", "S5 Tiền theo token", "Introduction to GenAI and Working with OpenAI APIs",
    ("Token là đơn vị tính tiền và đơn vị độ dài", "A token is the unit of cost and the unit of length."),
    ("Để một prompt dán cả cuốn sổ không bị ngạc nhiên khi hóa đơn và độ cụt cùng đến.", "So a prompt that pastes the whole notebook is not surprised when the bill and the cutoff arrive together."),
    ("Temperature không thêm sự thật. Độ dài prompt thì thêm tiền, và có một trần.", "Temperature adds no truth. Prompt length adds money, and there is a ceiling."),
    ("dài ra là đắt", "longer costs more"), ("quá trần thì cụt", "past the ceiling it cuts"),
    ("Bạn trả theo token vào và token ra. Một trần ngữ cảnh cắt phần không còn chỗ. Phần bị cắt là phần mô hình không thấy.", "You pay for tokens in and tokens out. A context ceiling cuts what no longer fits. The cut part is the part the model does not see."),
    ("Dán 200 trang chính sách vào một lần gọi có thể tốn tiền và vẫn mất đúng trang có điều khoản bạn cần, nếu trang đó bị cắt.", "Pasting 200 pages of policy into one call can cost money and still lose the page with the clause you need, if that page is what gets cut."),
    ("Đếm độ dài trước. Đưa phần việc cần, không đưa cả kho.", "Count the length first. Pass the part the job needs, not the whole warehouse."),
    ("Ví dụ minh họa: một bảng giá một trang nằm trọn trong trần thì lần gọi thấy nó. Cùng bảng giá bị chôn ở cuối một lần dán khổng lồ thì có thể không còn trong cửa sổ. Hóa đơn vẫn tính phần đã gửi.", "Illustration: a one-page price table that fits inside the ceiling is seen by the call. The same table buried at the end of a huge paste may no longer be in the window. The bill still counts what you sent."),
    [("Ước lượng token trước khi đưa vào sản phẩm.", "Estimate tokens before you put it in the product."), ("Cắt có chủ đích phần cần, đừng để trần tự cắt.", "Cut the part you need on purpose. Don't let the ceiling cut for you."), ("Token ra cũng tốn tiền. Đừng xin một bài dài nếu việc cần một câu.", "Output tokens cost money too. Don't ask for a long essay if the job needs one sentence.")],
    ("Token không khớp với số từ. Tiếng Việt và tiếng Anh nở khác nhau. Một trần là của cả message vào, lịch sử bạn gửi lại, và chỗ để viết ra. Hết chỗ viết thì câu cụt. Cụt không phải một kết luận. Log phải cho thấy phần nào thực sự vào request.", "Tokens do not match the word count. Vietnamese and English expand differently. A ceiling covers the input messages, the history you resend, and the room left to write. Run out of room to write and the sentence stops. A stopped sentence is not a conclusion. The log has to show what actually entered the request."),
    ("Bị cắt là không thấy. Vẫn mất tiền phần đã gửi.", "What was cut was not seen. You still pay for what you sent."),
)
K("ga-prompt", C6, "s-c0a1c92ed703", "Prompt parts", "C6 · GenAI", "S6 Việc, ngữ cảnh, dạng", "Introduction to GenAI and Working with OpenAI APIs",
    ("Một prompt là việc, ngữ cảnh, và dạng đầu ra", "A prompt is the task, the context, and the output shape."),
    ("Để một lời «hãy thông minh» không thay cho ba phần đó.", "So a line that says “be smart” does not replace those three parts."),
    ("Token đã có trần. Phần được đưa vào trần nên là việc, ngữ cảnh thật, và dạng bạn cần.", "Tokens already have a ceiling. What you put under that ceiling should be the task, the real context, and the shape you need."),
    ("đủ ba phần", "the three parts"), ("một lời cổ vũ", "a pep talk"),
    ("Task là làm gì. Context là tài liệu và các ràng buộc của lần này. Format là đầu ra trông thế nào, để máy hoặc người sau đọc được.", "The task is what to do. The context is the documents and the limits of this call. The format is what the output should look like, so a machine or the next person can read it."),
    ("«Viết cho hay» không nói dùng bảng nào, cũng không nói cần một đoạn hay một bảng.", "“Write it well” does not say which table to use, and does not say whether you need a paragraph or a table."),
    ("Đủ ba phần. Bỏ lời cổ vũ.", "Include the three parts. Drop the pep talk."),
    ("Ví dụ minh họa: việc là trả lời có được hoàn tiền không. Ngữ cảnh là đoạn chính sách đính kèm, không được bịa thêm. Dạng là một câu có dẫn đúng chỗ trong đoạn đó, hoặc nói «không thấy trong đoạn».", "Illustration: the task is to answer whether a refund is allowed. The context is the attached policy passage, and it must not invent more. The format is one sentence that points at the exact place in that passage, or says “not in the passage”."),
    [("Viết việc thành một động từ.", "Write the task as a verb."), ("Dán đúng đoạn cần, không dán cả kho.", "Paste the passage you need, not the whole warehouse."), ("Nói dạng đầu ra: một câu, một bảng, hay một mã.", "Say the output shape: one sentence, a table, or a code.")],
    ("Ba phần này không làm mô hình trở thành một cơ sở dữ liệu. Chúng chỉ giảm kiểu sai «không biết việc» và «bịa thêm vì không có dạng». Context vẫn phải là nguồn thật của lần gọi. Format là một giao kèo để kiểm, không phải một sự thật mới.", "These three parts do not turn the model into a database. They only reduce the kind of failure where it does not know the job and where it invents more because there was no shape. The context still has to be the real source of this call. The format is a contract you can check, not a new truth."),
    ("«Hãy cẩn thận» không phải một ngữ cảnh.", "“Be careful” is not a context."),
)
K("ga-few", C6, "s-c0a1c92ed703", "Few-shot", "C6 · GenAI", "S6 Vài ví dụ", "Introduction to GenAI and Working with OpenAI APIs",
    ("Vài ví dụ chỉ ra một dạng. Chúng không chứng minh dạng đó đúng với đời", "A few examples show a shape. They do not prove the shape is true of the world."),
    ("Để hai ví dụ trong prompt không thành hai bằng chứng thị trường.", "So two examples in the prompt do not become two pieces of market evidence."),
    ("Prompt đã có việc, ngữ cảnh, dạng. Few-shot là thêm vài cặp minh họa dạng đó.", "The prompt already has a task, a context, and a shape. Few-shot adds a few pairs that illustrate that shape."),
    ("một dạng để bắt chước", "a shape to copy"), ("không phải bằng chứng", "not evidence"),
    ("Bạn đưa một vài đầu vào và đầu ra mẫu. Mô hình noi dạng. Các mẫu không phải một tập chấm, cũng không phải một khảo sát.", "You give a few sample inputs and outputs. The model follows the shape. The samples are not a scoring set, and they are not a survey."),
    ("Hai ví dụ «khách trẻ thì thích A» không đo được khách trẻ. Nó chỉ dạy mô hình viết theo kiểu đó.", "Two examples of “young customers like A” do not measure young customers. They only teach the model to write in that style."),
    ("Dùng ví dụ để khóa dạng câu. Đừng dùng ví dụ thay cho dữ liệu.", "Use examples to lock the shape of the sentence. Don't use examples instead of data."),
    ("Ví dụ minh họa: muốn đầu ra là «có / không / không thấy trong đoạn». Đưa ba mẫu đúng dạng đó. Ba mẫu không làm đoạn chính sách trở thành đúng. Chúng chỉ làm câu trả lời dễ kiểm.", "Illustration: you want the output to be “yes / no / not in the passage”. Give three samples of that shape. The three samples do not make the policy passage true. They only make the answer easier to check."),
    [("Ví dụ đúng dạng bạn sẽ kiểm.", "Examples of the shape you will check."), ("Đừng nhét một kết luận chưa có số vào ví dụ.", "Don't put a conclusion that has no number into an example."), ("Ví dụ mâu thuẫn thì đừng ngạc nhiên khi đầu ra mâu thuẫn.", "Contradictory examples, then don't be surprised by a contradictory output.")],
    ("Few-shot nằm trong prompt, nên nó tốn token và nó là data của lần gọi, không phải fine-tune. Một ví dụ sai dạng dạy sai dạng rất đều, nhất là khi temperature thấp. Đó là sự ổn định của một cái sai, không phải độ chính xác.", "Few-shot sits in the prompt, so it costs tokens, and it is data of this call, not a fine-tune. A sample with the wrong shape teaches the wrong shape very steadily, especially at low temperature. That is the stability of a mistake, not accuracy."),
    ("Ví dụ trong prompt không phải một mẫu điều tra.", "An example in the prompt is not a survey sample."),
)
K("ga-cot", C6, "s-c0a1c92ed703", "Chain of thought", "C6 · GenAI", "S6 Chuỗi bước", "Introduction to GenAI and Working with OpenAI APIs",
    ("Bảo viết từng bước không phải một chứng minh", "Asking for steps is not a proof."),
    ("Để một chuỗi lý luận trôi không được đóng dấu là đã kiểm.", "So a fluent chain of reasons is not stamped as checked."),
    ("Few-shot khóa dạng. Chain-of-thought xin thêm các bước. Các bước vẫn là token.", "Few-shot locks a shape. Chain-of-thought asks for steps as well. The steps are still tokens."),
    ("các bước trôi", "fluent steps"), ("không phải chứng minh", "not a proof"),
    ("Xin mô hình viết từng bước có thể đổi câu trả lời. Các bước có thể mạch lạc và sai.", "Asking the model to write steps can change the answer. The steps can be coherent and wrong."),
    ("Một chuỗi «vì A nên B nên giá là 100» không tra bảng. Nó chỉ là một chuỗi chữ.", "A chain “because A, therefore B, therefore the price is 100” does not look up a table. It is only a chain of text."),
    ("Đọc bước nào trỏ tới nguồn trong context. Bước không trỏ thì bỏ.", "Read which step points at a source in the context. A step that does not point is dropped."),
    ("Ví dụ minh họa: context không có giá. Chuỗi bước vẫn viết ra một giá và một lý do nghe được. Lý do đó không phải một nguồn. Đừng thu theo giá đó.", "Illustration: the context has no price. The chain of steps still writes a price and a reason that sounds fine. That reason is not a source. Don't collect that price."),
    [("Chỉ dùng các bước có trỏ đúng chỗ trong context.", "Only use steps that point at the exact place in the context."), ("Bước nào bịa một số: coi cả câu là chưa kiểm.", "A step that invents a number: treat the whole answer as unchecked."), ("Đừng đưa chuỗi bước cho khách như một biên bản.", "Don't hand the chain of steps to a customer as a record.")],
    ("Chain-of-thought không phải một suy diễn thống kê và không phải một lời giải solver. Nó không có góc, không có tập chấm, không có #N/A khi thiếu. Một bước trung gian sai vẫn có thể dẫn tới một câu cuối nghe hay. Kiểm câu cuối bằng nguồn, đừng kiểm bằng độ mượt của các bước.", "Chain-of-thought is not a statistical inference and not a solver solution. It has no corner, no scoring set, and no #N/A when something is missing. A wrong middle step can still lead to a last sentence that sounds good. Check the last sentence against the source. Don't check it by how smooth the steps are."),
    ("Mượt không phải đã chứng minh.", "Smooth is not the same as proved."),
)
